/* THE EYES ARE ON THE BALL. Each eye is a point on the
   sphere; the pointer turns the ball, and the eye heading for
   the rim moves less and narrows — foreshortening is what makes
   a flat circle read as round. */
const z0 = Math.sqrt(1 - x0 * x0 - y0 * y0);
const x1 = x0 * Math.cos(yaw) + z0 * Math.sin(yaw);
const z1 = -x0 * Math.sin(yaw) + z0 * Math.cos(yaw);
const y2 = y0 * Math.cos(pitch) - z1 * Math.sin(pitch);
const z2 = y0 * Math.sin(pitch) + z1 * Math.cos(pitch);
eye.setAttribute("transform",
  `translate(${50 + x1 * R} ${50 + y2 * R}) scale(${0.35 + 0.65 * z2} 1)`);
